    model: `FUNCTION Check() RETURNS STRING
    DECLARE Odd : INTEGER
    DECLARE Even : INTEGER
    DECLARE Index : INTEGER
    Odd <- 0
    Even <- 0
    FOR Index <- 1 TO 100
        IF Index MOD 2 = 0 THEN
            Even <- Even + Data[Index]
        ELSE
            Odd <- Odd + Data[Index]
        ENDIF
    NEXT Index
    IF Odd > Even THEN
        RETURN "Odd"
    ELSE
        IF Even > Odd THEN
            RETURN "Even"
        ELSE
            RETURN "Same"
        ENDIF
    ENDIF
ENDFUNCTION`,
